const outcomes = max.batch(args.queries.map(query => ({tool: "web_search", args: {query, max_results: args.limit}})));
const rows = outcomes.map((outcome, index) => {
  if (outcome.outcome !== "succeeded" && outcome.outcome !== "committed") return {query: args.queries[index], outcome: outcome.outcome, error: {...outcome.error, message: String(outcome.error?.message ?? "").slice(0, 512)}};
  if (!Array.isArray(outcome.value?.results)) throw new Error("web_search returned no results array");
  const results = outcome.value.results;
  return {query: args.queries[index], outcome: outcome.outcome,
    answer: typeof outcome.value.answer === "string" ? outcome.value.answer.slice(0, 512) : null,
    results: results.slice(0, args.limit).map(row => ({title: String(row.title ?? "").slice(0, 160), url: String(row.url ?? "").slice(0, 1024), snippet: String(row.snippet ?? "").slice(0, 400)})),
    omitted_results: Math.max(0, results.length - args.limit)};
});
// 20k UTF-16 units fit below the host 64 KiB UTF-8 result limit.
while (JSON.stringify(rows).length > 20000) {
  const row = [...rows].reverse().find(row => row.results?.length);
  if (!row) throw new Error("search summary exceeds output budget");
  row.results.pop(); row.omitted_results += 1;
}
return rows;
